<div class="card"><div class="card-header section-card-header"><span class="section-card-icon"><i class="mdi mdi-account-group-outline"></i></span><span>Daftar pengguna</span></div><div class="card-body table-responsive"><table id="userTable" class="table align-middle w-100"><thead><tr><th>Nama</th><th>Username</th><th>Email</th><th>Role</th><th>Status</th><th>Aksi</th></tr></thead></table></div></div>
<div class="modal fade" id="userModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><form class="modal-content" id="userForm"><div class="modal-header"><div class="fw-bold modal-title">Tambah Pengguna</div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" id="userId"><div class="row g-2"><div class="col-12"><label class="form-label">Nama</label><input class="form-control" name="name"><div class="field-error" data-error="name"></div></div><div class="col-6"><label class="form-label">Username</label><input class="form-control" name="username"><div class="field-error" data-error="username"></div></div><div class="col-6"><label class="form-label">Email</label><input class="form-control" type="email" name="email"><div class="field-error" data-error="email"></div></div><div class="col-6"><label class="form-label">Role</label><select class="form-select" name="role"><option value="cashier">Kasir</option><option value="admin">Admin</option></select></div><div class="col-6"><label class="form-label">Status</label><select class="form-select" name="is_active"><option value="1">Aktif</option><option value="0">Nonaktif</option></select></div><div class="col-6"><label class="form-label">Kata sandi</label><input class="form-control" type="password" name="password"><div class="field-error" data-error="password"></div></div><div class="col-6"><label class="form-label">Konfirmasi</label><input class="form-control" type="password" name="password_confirmation"></div></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Batal</button><button class="btn btn-primary" id="saveUser" type="submit">Simpan</button></div></form></div></div>
@endsection
@push('scripts')<script>
$(function(){const base=@json(route('users.index'));const modal=bootstrap.Modal.getOrCreateInstance('#userModal');const table=$('#userTable').DataTable({ajax:{url:base,dataSrc:'data'},columns:[{data:'name',render:escapeHtml},{data:'username',render:escapeHtml},{data:'email',defaultContent:'-',render:escapeHtml},{data:'role',render:v=>v==='admin'?'Admin':'Kasir'},{data:'is_active',render:v=>v?'<span class="badge bg-success">Aktif</span>':'<span class="badge bg-secondary">Nonaktif</span>'},{data:null,orderable:false,render:d=>`<div class="d-flex gap-1"><button class="btn btn-light btn-sm edit-user" data-id="${d.id}"><i class="mdi mdi-pencil"></i></button><button class="btn btn-danger btn-sm delete-user" data-id="${d.id}"><i class="mdi mdi-delete"></i></button></div>`}]});
$('#addUser').click(()=>{$('#userForm')[0].reset();$('#userId').val('');clearErrors('#userForm');$('.modal-title').text('Tambah Pengguna');modal.show()});
$('#userTable').on('click','.edit-user',function(){$.get(`${base}/${$(this).data('id')}`).done(r=>{const d=r.data;$('#userForm')[0].reset();$('#userId').val(d.id);['name','username','email','role','is_active'].forEach(k=>$('#userForm').find(`[name="${k}"]`).val(d[k]===true?1:d[k]===false?0:d[k]));clearErrors('#userForm');$('.modal-title').text('Ubah Pengguna');modal.show()})});
$('#userForm').submit(function(e){e.preventDefault();const id=$('#userId').val(),button=$('#saveUser');buttonLoading(button,true);$.ajax({url:id?`${base}/${id}`:base,type:id?'PUT':'POST',data:$(this).serialize()}).done(r=>{modal.hide();table.ajax.reload(null,false);notify(r.message)}).fail(x=>{showErrors('#userForm',x.responseJSON?.errors);notify(x.responseJSON?.message||'Gagal menyimpan.',false)}).always(()=>buttonLoading(button,false))});
let id;const dm=bootstrap.Modal.getOrCreateInstance('#deleteModal');$('#userTable').on('click','.delete-user',function(){const row=table.row($(this).closest('tr')).data();id=row.id;$('#deleteName').text(row.name);dm.show()});$('#confirmDelete').click(function(){const b=this;buttonLoading(b,true);$.ajax({url:`${base}/${id}`,type:'DELETE'}).done(r=>{dm.hide();table.ajax.reload(null,false);notify(r.message)}).fail(x=>notify(x.responseJSON?.message||'Gagal menghapus.',false)).always(()=>buttonLoading(b,false))});});
</script>@endpush
